sys_variable_value.value:
(function execute(inputs, outputs) {

    var fieldMapping = {
        "v_cumprimento_caixa_liquido": "cumprimento_caixa_liquido",
        "v_meta_despesa_com_pessoal": "meta_despesa_com_pessoal",
        "v_meta_caixa_liquido": "meta_caixa_liquido",
        "v_cumprimento_arrecadacao_propria": "cumprimento_arrecadacao_propria",
        "v_valor_apurado_caixa_liquido": "valor_apurado_caixa_liquido",
        "v_cumprimento_despesa_com_pessoal": "cumprimento_despesa_com_pessoal",
        "v_valor_apurado_arrecadacao_propria": "valor_apurado_arrecadacao_propria",
        "v_meta_arrecadacao_propria": "meta_arrecadacao_propria",
        "v_valor_apurado_despesa_com_pessoal": "valor_apurado_despesa_com_pessoal",
        "v_valor_apurado_resultado_primario": "valor_apurado_resultado_primario",
        "v_meta_resultado_primario": "meta_resultado_primario",
        "v_cumprimento_endividamento": "cumprimento_endividamento",
        "v_meta_endividamento": "meta_endividamento",
        "v_valor_apurado_endividamento": "valor_apurado_endividamento",
        "v_cumprimento_resultado_primario": "cumprimento_resultado_primario",
        "v_ano": "ano"
    };

    var grMultiRow = new GlideRecord('sc_multi_row_question_answer');
    grMultiRow.addEncodedQuery(
        'row_index=' + inputs.row_index +
        '^parent_id=' + inputs.parent_id
    );
    grMultiRow.query();

    while (grMultiRow.next()) {
        var questionName = grMultiRow.item_option_new.name;
        var value = grMultiRow.getValue('value');

        if (fieldMapping[questionName]) {
            fieldMapping[questionName] = value;
        }
    }

    outputs.cumprimento_caixa_liquido          = fieldMapping["v_cumprimento_caixa_liquido"];
    outputs.meta_despesa_com_pessoal           = fieldMapping["v_meta_despesa_com_pessoal"];
    outputs.meta_caixa_liquido                 = fieldMapping["v_meta_caixa_liquido"];
    outputs.cumprimento_arrecadacao_propria    = fieldMapping["v_cumprimento_arrecadacao_propria"];
    outputs.valor_apurado_caixa_liquido        = fieldMapping["v_valor_apurado_caixa_liquido"];
    outputs.cumprimento_despesa_com_pessoal    = fieldMapping["v_cumprimento_despesa_com_pessoal"];
    outputs.valor_apurado_arrecadacao_propria  = fieldMapping["v_valor_apurado_arrecadacao_propria"];
    outputs.meta_arrecadacao_propria           = fieldMapping["v_meta_arrecadacao_propria"];
    outputs.valor_apurado_despesa_com_pessoal  = fieldMapping["v_valor_apurado_despesa_com_pessoal"];
    outputs.valor_apurado_resultado_primario   = fieldMapping["v_valor_apurado_resultado_primario"];
    outputs.meta_resultado_primario            = fieldMapping["v_meta_resultado_primario"];
    outputs.cumprimento_endividamento          = fieldMapping["v_cumprimento_endividamento"];
    outputs.meta_endividamento                 = fieldMapping["v_meta_endividamento"];
    outputs.valor_apurado_endividamento        = fieldMapping["v_valor_apurado_endividamento"];
    outputs.cumprimento_resultado_primario     = fieldMapping["v_cumprimento_resultado_primario"];
    outputs.ano                                 = fieldMapping["v_ano"];

})(inputs, outputs);

